// ═══════════════════════════════════════════════
// AGENTGUARD — ContextBudget v1.0
// Tool result budgeting + two-tier compaction
// ═══════════════════════════════════════════════

const config = {
  maxResultChars: 8000,
  previewHeadChars: 500,
  previewTailChars: 200,
  compactionThreshold: 0.80,
  protectedTailTurns: 3,
  maxConsecutiveCompactions: 3,
  summaryModel: 'gemma4:e4b',
  summaryEndpoint: 'http://localhost:11434/v1/chat/completions'  // CONFIGURE: set your Ollama or OpenAI-compatible endpoint,
  persistPath: '/tmp/agentguard/tool_results',
  contextWindowTokens: 128000,
  charsPerToken: 4
};

const input = $input.first().json;
const toolResults = input.toolResults || [];
const conversationHistory = input.conversationHistory || [];
const turnNumber = input.turnNumber || 0;
const compactionFailures = input._agCompactionFailures || 0;

// ─── Tier 0: Tool Result Budgeting ───
function budgetToolResults(results) {
  return results.map((result, i) => {
    const content = typeof result.content === 'string' ? result.content : JSON.stringify(result.content);
    const charCount = content.length;

    if (charCount <= config.maxResultChars) {
      return { ...result, _agBudgeted: false, _agOriginalChars: charCount };
    }

    // Truncate with preview
    const head = content.slice(0, config.previewHeadChars);
    const tail = content.slice(-config.previewTailChars);
    const fileRef = `${config.persistPath}/${Date.now()}_tool_${i}.txt`;

    const truncated = [
      head,
      `\n\n[... ${charCount - config.previewHeadChars - config.previewTailChars} chars truncated — full result saved to ${fileRef} ...]\n\n`,
      tail
    ].join('');

    return {
      ...result,
      content: truncated,
      _agBudgeted: true,
      _agOriginalChars: charCount,
      _agTruncatedTo: truncated.length,
      _agFileRef: fileRef,
      _agFullContent: content  // Pass to file writer
    };
  });
}

// ─── Tier 1: Microcompact (zero cost) ───
function microcompact(history, currentTurn) {
  return history.map((msg, i) => {
    // Only process tool results
    if (msg.role !== 'tool' && !msg._agIsToolResult) return msg;

    // Protect recent turns
    const msgTurn = msg._agTurn || 0;
    if (currentTurn - msgTurn <= config.protectedTailTurns) return msg;

    // Already compacted
    if (msg._agMicrocompacted) return msg;

    return {
      ...msg,
      content: '[Previous tool result cleared — re-execute tool if needed]',
      _agMicrocompacted: true,
      _agOriginalChars: (msg.content || '').length,
      _agClearedAtTurn: currentTurn
    };
  });
}

// ─── Tier 2: Auto-compact (model call) ───
function estimateTokens(history) {
  const totalChars = history.reduce((sum, msg) => {
    const content = typeof msg.content === 'string' ? msg.content : JSON.stringify(msg.content || '');
    return sum + content.length;
  }, 0);
  return Math.ceil(totalChars / config.charsPerToken);
}

function needsAutoCompact(history) {
  const tokens = estimateTokens(history);
  const usage = tokens / config.contextWindowTokens;
  return usage >= config.compactionThreshold;
}

function buildSummaryPrompt(history, protectedCount) {
  const toSummarize = history.slice(0, -protectedCount);
  const text = toSummarize.map(m => `${m.role}: ${typeof m.content === 'string' ? m.content : JSON.stringify(m.content)}`).join('\n');

  return {
    model: config.summaryModel,
    messages: [{
      role: 'user',
      content: `Summarize this conversation context in 3-5 sentences. Preserve: key decisions, file paths modified, current task state, any numbers or IDs. Drop: verbose tool outputs, repeated information, greetings.\n\n${text}`
    }],
    max_tokens: 500,
    temperature: 0.1
  };
}

// ─── Execute Pipeline ───

// Step 1: Budget tool results
const budgetedResults = budgetToolResults(toolResults);
const savedToFile = budgetedResults.filter(r => r._agBudgeted);

// Step 2: Microcompact history
const microcompacted = microcompact(conversationHistory, turnNumber);
const microcompactedCount = microcompacted.filter(m => m._agMicrocompacted && m._agClearedAtTurn === turnNumber).length;

// Step 3: Check if auto-compact needed
const needsCompact = needsAutoCompact(microcompacted);
const compactionBlocked = compactionFailures >= config.maxConsecutiveCompactions;

let autoCompactRequest = null;
if (needsCompact && !compactionBlocked) {
  autoCompactRequest = buildSummaryPrompt(microcompacted, config.protectedTailTurns);
}

return [{
  json: {
    // Budgeted tool results (use these instead of originals)
    toolResults: budgetedResults.map(r => {
      const { _agFullContent, ...clean } = r;
      return clean;
    }),

    // Files to persist (pipe to file writer node)
    filesToPersist: savedToFile.map(r => ({
      path: r._agFileRef,
      content: r._agFullContent
    })),

    // Compacted history
    conversationHistory: microcompacted,

    // Compaction status
    microcompactedCount,
    needsAutoCompact: needsCompact,
    compactionBlocked,
    autoCompactRequest,

    // Token estimate
    estimatedTokens: estimateTokens(microcompacted),
    contextUsage: (estimateTokens(microcompacted) / config.contextWindowTokens).toFixed(3),

    // State tracking
    _agCompactionFailures: compactionBlocked ? compactionFailures : (needsCompact ? compactionFailures : 0),
    _agTurnNumber: turnNumber,

    // Audit
    _agTimestamp: new Date().toISOString(),
    _agBudgetReport: {
      totalResults: toolResults.length,
      truncated: savedToFile.length,
      charsSaved: savedToFile.reduce((s, r) => s + r._agOriginalChars - r._agTruncatedTo, 0),
      microcompacted: microcompactedCount
    }
  }
}];

// Replace old messages with summary
const input = $input.first().json;
const summary = input?.choices?.[0]?.message?.content || 'Summary unavailable.';

return [{
  json: {
    summary,
    action: 'replace_history_prefix',
    _agAutoCompacted: true,
    _agTimestamp: new Date().toISOString()
  }
}];
